const conv = ($('get_data').first().json.conversation || '').toString().toLowerCase().trim();
const btn = ($('get_data').first().json.btn_data || '').toString().toLowerCase().trim();
const raw = conv || btn;

const opcoes = {
  '1': 'suporte', 'btn1': 'suporte', 'suporte': 'suporte',
  '2': 'financeiro', 'btn2': 'financeiro', 'financeiro': 'financeiro',
  'financeiro e com': 'financeiro', 'financeiro e com.': 'financeiro',
  '3': 'agrotech', 'btn3': 'agrotech', 'agrotech': 'agrotech'
};

const opcao = opcoes[raw] || 'erro';

return [{ json: { rota: opcao, departamento: opcao === 'erro' ? '' : opcao } }];

const conv = ($('get_data').first().json.conversation || '').toString().toLowerCase().trim();
const btn = ($('get_data').first().json.btn_data || '').toString().toLowerCase().trim();
const raw = conv || btn;

// 1. Mapeia a entrada do utilizador para uma chave padrão
let chave = '';
if (['1', 'btn1', 'fiscal'].includes(raw)) chave = 'fiscal';
else if (['2', 'btn2', 'financeiro'].includes(raw)) chave = 'financeiro';
else if (['3', 'btn3', 'operacional'].includes(raw)) chave = 'operacional';

// 2. Define o departamento e a fila para cada chave
const config = {
  'fiscal': { departamento: 'suporte_fiscal', fila: 'N2-Suporte' },
  'financeiro': { departamento: 'Financeiro', fila: 'Financeiro' },
  'operacional': { departamento: 'suporte_operacional', fila: 'N1-Suporte' }
};

// 3. Obtém o resultado ou retorna erro
const resultado = config[chave];

return [{
  json: {
    input_recebido: raw,
    rota: resultado ? 'sucesso' : 'erro',
    departamento: resultado ? resultado.departamento : '',
    fila: resultado ? resultado.fila : ''
  }
}];

// ==========================================
// CONFIGURAÇÃO
// ==========================================
const ALLOW_OFFLINE_FALLBACK = false; // nunca escolher usuários offline

const DEPTO_PARA_FILA = {
  suporte: 6,
  suporte_fiscal: 7,
  suporte_operacional: 6,
  financeiro: 2,
  suporte_financeiro: 2,
  agrotech: 4,
};

const NOME_FILA_PARA_ID = {
  'n1-suporte': 6,
  'n2-suporte': 7,
  'n3-suporte': 8,
  'suporte': 1,
  'financeiro': 2,
  'agrotech': 4,
  'vendas': 3
};

const DEPTO_PREFERIDOS = {
  suporte_fiscal: [9, 7],
  suporte_financeiro: [4, 5],
  financeiro: [4, 5],
  suporte_operacional: [5, 4, 10],
  agrotech: [],
  suporte: []
};

const FILA_FALLBACK_ID = 6;
const FILA_FALLBACK_NOME = 'N1-Suporte';

// DEBUG: habilite para ver logs no n8n
const DEBUG = false;

// ==========================================
// HELPERS
// ==========================================
function obterDepartamentoAtual() {
  let depto = '';
  try { depto = $('parse_menu_principal').first().json.departamento || ''; } catch (e) {}
  if (!depto) {
    try { depto = $('parse_menu_suporte').first().json.departamento || ''; } catch (e) {}
  }
  return String(depto || '').trim().toLowerCase();
}

function mapearUsuariosEFilas(usuariosRaw) {
  const filasCatalogo = {};
  const usuariosPorId = {};

  // Permitir apenas este admin específico (Kariny). Ajuste se quiser incluir outros admins.
  const ADMIN_ALLOWLIST = [4];

  for (const usuario of usuariosRaw) {
    // pula admins, exceto os que estão na allowlist
    if (usuario.profile === 'admin' && !ADMIN_ALLOWLIST.includes(usuario.id)) continue;

    usuariosPorId[String(usuario.id)] = {
      userId: usuario.id,
      name: usuario.name,
      isOnline: usuario.isOnline === true,
      qtdAtendimentos: 0,
      filas: []
    };

    if (!usuario?.queues?.length) continue;

    for (const fila of usuario.queues) {
      const queueId = fila.id;
      const queueName = fila.queue;

      usuariosPorId[String(usuario.id)].filas.push({ queueId, queueName });

      const key = String(queueId);
      if (!filasCatalogo[key]) {
        filasCatalogo[key] = { queueId, queueName, usuarios: [] };
      }
      if (!filasCatalogo[key].usuarios.includes(usuario.id)) {
        filasCatalogo[key].usuarios.push(usuario.id);
      }
    }
  }

  return { filasCatalogo, usuariosPorId };
}

function findQueueKeyByName(filasCatalogo, queueName) {
  if (!queueName) return null;
  const target = String(queueName).trim().toLowerCase();
  for (const key in filasCatalogo) {
    const qName = String(filasCatalogo[key].queueName || '').trim().toLowerCase();
    if (qName && qName === target) return key;
  }
  return null;
}

// Resolve chave de fila a partir de queueId (numérico/string) ou nome (departamento)
function resolveQueueKey(queueId, filasCatalogo, departamento) {
  if (queueId === undefined || queueId === null) return null;

  // 1) chave direta (numérica ou string)
  if (filasCatalogo[String(queueId)]) return String(queueId);

  // 2) procura por entrada cujo queueId interno seja igual (caso a chave seja string)
  for (const key in filasCatalogo) {
    if (String(filasCatalogo[key].queueId) === String(queueId)) return key;
  }

  // 3) tenta achar por nome usando departamento (departamento já vem normalizado)
  if (departamento) {
    for (const key in filasCatalogo) {
      const qName = String(filasCatalogo[key].queueName || '').trim().toLowerCase();
      if (qName === departamento) return key;
    }
  }

  // 4) tenta mapear queueId para nome via NOME_FILA_PARA_ID (inversa)
  for (const name in NOME_FILA_PARA_ID) {
    if (String(NOME_FILA_PARA_ID[name]) === String(queueId)) {
      for (const key in filasCatalogo) {
        const qName = String(filasCatalogo[key].queueName || '').trim().toLowerCase();
        if (qName === name) return key;
      }
      return String(queueId);
    }
  }

  // 5) fallback: procura pelo nome padrão da fila fallback
  for (const key in filasCatalogo) {
    const qName = String(filasCatalogo[key].queueName || '').trim().toLowerCase();
    if (qName === FILA_FALLBACK_NOME.toLowerCase()) return key;
  }

  // 6) se nada encontrado, retorna queueId como string
  return String(queueId);
}

// Resolve chave por nome (tenta catálogo, depois dicionário NOME_FILA_PARA_ID)
function resolveQueueKeyByName(filasCatalogo, queueName) {
  if (!queueName) return null;
  const normalized = String(queueName).trim().toLowerCase();

  // 1) procura por nome no catálogo
  const byName = findQueueKeyByName(filasCatalogo, normalized);
  if (byName) return byName;

  // 2) tenta mapear via dicionário NOME_FILA_PARA_ID
  const mappedId = NOME_FILA_PARA_ID[normalized];
  if (mappedId !== undefined) {
    const key = String(mappedId);
    if (!filasCatalogo[key]) {
      filasCatalogo[key] = { queueId: mappedId, queueName: queueName, usuarios: [] };
    }
    return key;
  }

  return null;
}

// ==========================================
// PROCESSAMENTO DOS LOGS DO BANCO
// ==========================================
function processarCargaDeAtendimentos(itensInput, usuariosPorId, filasCatalogo, departamento) {
  let logsFlat = [];

  for (const item of itensInput) {
    if (Array.isArray(item.json)) logsFlat.push(...item.json);
    else logsFlat.push(item.json);
  }
  if (logsFlat.length === 0) return;

  const departamentoNorm = String(departamento || '').trim().toLowerCase();

  // Agrupa por id_user somando contagem_transferencia e mantendo último nome/fila/depto
  const agregados = {};
  for (const log of logsFlat) {
    const uid = Number(log.id_user);
    if (!uid) continue;
    const cont = Number(log.contagem_transferencia || 0);
    const nome = log.atendente_nome || `user_${uid}`;
    const filaNome = log.fila ? String(log.fila).trim() : null;
    const logDepto = log.depto ? String(log.depto).trim().toLowerCase() : null;

    if (!agregados[uid]) agregados[uid] = { uid, contagem: 0, nome, filaNome, logDepto };
    agregados[uid].contagem += cont;
    agregados[uid].nome = nome;
    if (filaNome) agregados[uid].filaNome = filaNome;
    if (logDepto) agregados[uid].logDepto = logDepto;
  }

  for (const k in agregados) {
    const a = agregados[k];
    const uid = Number(a.uid);

    // Atualiza ou cria placeholder do usuário
    if (usuariosPorId[String(uid)]) {
      usuariosPorId[String(uid)].qtdAtendimentos = a.contagem;
      if (!usuariosPorId[String(uid)].name) usuariosPorId[String(uid)].name = a.nome;
    } else {
      usuariosPorId[String(uid)] = {
        userId: uid,
        name: a.nome,
        isOnline: false,
        qtdAtendimentos: a.contagem,
        filas: []
      };
    }

    // 1) Injeta por fila do log (se houver)
    if (a.filaNome) {
      let queueKey = findQueueKeyByName(filasCatalogo, a.filaNome);

      if (!queueKey) {
        const normalized = a.filaNome.trim().toLowerCase().replace(/\s+/g, '-');
        const mappedId = NOME_FILA_PARA_ID[normalized];
        if (mappedId !== undefined) {
          const key = String(mappedId);
          if (!filasCatalogo[key]) filasCatalogo[key] = { queueId: mappedId, queueName: a.filaNome, usuarios: [] };
          queueKey = key;
        }
      }

      if (!queueKey) {
        const fakeKey = `bank_${a.filaNome.replace(/\s+/g, '_').toLowerCase()}`;
        if (!filasCatalogo[fakeKey]) filasCatalogo[fakeKey] = { queueId: fakeKey, queueName: a.filaNome, usuarios: [] };
        queueKey = fakeKey;
      }

      if (queueKey) {
        if (!filasCatalogo[queueKey].usuarios.includes(uid)) filasCatalogo[queueKey].usuarios.push(uid);
        if (!usuariosPorId[String(uid)].filas.find(f => String(f.queueName || '').trim().toLowerCase() === String(filasCatalogo[queueKey].queueName || '').trim().toLowerCase())) {
          usuariosPorId[String(uid)].filas.push({ queueId: filasCatalogo[queueKey].queueId, queueName: filasCatalogo[queueKey].queueName });
        }
      }
    }

    // 2) Injeta por depto (se log.depto corresponde ao departamento atual)
    if (a.logDepto && departamentoNorm && a.logDepto === departamentoNorm) {
      let deptQueueKey = findQueueKeyByName(filasCatalogo, departamentoNorm);

      if (!deptQueueKey) {
        const mappedId = NOME_FILA_PARA_ID[departamentoNorm];
        if (mappedId !== undefined) {
          const key = String(mappedId);
          if (!filasCatalogo[key]) filasCatalogo[key] = { queueId: mappedId, queueName: departamentoNorm, usuarios: [] };
          deptQueueKey = key;
        }
      }

      if (!deptQueueKey) {
        const fakeDeptKey = `bank_${departamentoNorm.replace(/\s+/g, '_')}`;
        if (!filasCatalogo[fakeDeptKey]) filasCatalogo[fakeDeptKey] = { queueId: fakeDeptKey, queueName: departamentoNorm, usuarios: [] };
        deptQueueKey = fakeDeptKey;
      }

      if (!filasCatalogo[deptQueueKey].usuarios.includes(uid)) filasCatalogo[deptQueueKey].usuarios.push(uid);
      if (!usuariosPorId[String(uid)].filas.find(f => String(f.queueName || '').trim().toLowerCase() === String(filasCatalogo[deptQueueKey].queueName || '').trim().toLowerCase())) {
        usuariosPorId[String(uid)].filas.push({ queueId: filasCatalogo[deptQueueKey].queueId, queueName: filasCatalogo[deptQueueKey].queueName });
      }
    }
  }
}

// ==========================================
// ESCOLHA DE ATENDENTE (NUNCA ESCOLHER OFFLINE)
// ==========================================
function escolherAtendentePorCarga(targetQueueKey, preferidosIds, filasCatalogo, usuariosPorId, allowOffline = false) {
  if (!targetQueueKey && targetQueueKey !== 0) return { atendente: null, modo: 'somente_fila', usuariosDaFila: [] };

  const fila = filasCatalogo[String(targetQueueKey)];
  const todosIdsDaFila = (fila?.usuarios || []);

  if (todosIdsDaFila.length === 0) {
    return { atendente: null, modo: 'somente_fila', usuariosDaFila: [] };
  }

  const listaAtendentes = todosIdsDaFila.map(id => usuariosPorId[String(id)]).filter(Boolean);

  const usuariosDaFila = listaAtendentes.map(u => ({
    userId: u.userId,
    name: u.name,
    isOnline: u.isOnline,
    qtdAtendimentos: u.qtdAtendimentos
  }));

  // 1) tenta entre online apenas
  const listaOnline = listaAtendentes.filter(u => u.isOnline);
  if (listaOnline.length > 0) {
    const preferidosOnline = listaOnline.filter(u => preferidosIds.includes(u.userId));
    if (preferidosOnline.length > 0) {
      preferidosOnline.sort((a, b) => a.qtdAtendimentos - b.qtdAtendimentos || Math.random() - 0.5);
      return { atendente: preferidosOnline[0], modo: 'preferido_menor_carga', usuariosDaFila };
    }
    listaOnline.sort((a, b) => a.qtdAtendimentos - b.qtdAtendimentos || Math.random() - 0.5);
    return { atendente: listaOnline[0], modo: 'fila_menor_carga', usuariosDaFila };
  }

  // 2) se não houver online, sinaliza para transferir à próxima fila (escalonamento)
  return { atendente: null, modo: 'transfer_next', usuariosDaFila };
}

// ==========================================
// EXECUÇÃO PRINCIPAL COM ESCALONAMENTO ROBUSTO
// ==========================================
const itensDoBanco = $input.all();
const apiResp = $('buscar por usuarios online').first().json;
const usuariosRaw = apiResp.data || apiResp.body?.data || [];

const departamento = obterDepartamentoAtual();
const { filasCatalogo, usuariosPorId } = mapearUsuariosEFilas(usuariosRaw);

// Integra o banco ao catálogo (cria placeholders e buckets 'bank_*' quando necessário)
processarCargaDeAtendimentos(itensDoBanco, usuariosPorId, filasCatalogo, departamento);

if (DEBUG) {
  console.log('filasCatalogo (after processing):', JSON.stringify(filasCatalogo, null, 2));
  console.log('usuariosPorId (after processing):', JSON.stringify(usuariosPorId, null, 2));
}

// Resolve fila alvo
const queueId = DEPTO_PARA_FILA[departamento] || FILA_FALLBACK_ID;
const preferidos = DEPTO_PREFERIDOS[departamento] || [];
let targetQueueKey = resolveQueueKey(queueId, filasCatalogo, departamento);
if (!targetQueueKey) targetQueueKey = resolveQueueKeyByName(filasCatalogo, departamento) || String(queueId);

// === Construção robusta de queueKeysToTry ===
// Ordem nominal de escalonamento (nomes preferenciais)
const escalationNames = [
  null, // placeholder para fila alvo
  'n1-suporte',
  'n2-suporte',
  'n3-suporte',
  'financeiro'
];

// Constrói lista inicial com target
const triedKeys = new Set();
const queueKeysToTry = [];
if (targetQueueKey !== null && targetQueueKey !== undefined) {
  queueKeysToTry.push(String(targetQueueKey));
  triedKeys.add(String(targetQueueKey));
}

// 1) adiciona filas explicitamente mapeadas por nome (se existirem no catálogo)
for (const name of escalationNames.slice(1)) {
  const key = resolveQueueKeyByName(filasCatalogo, name);
  if (key && !triedKeys.has(String(key))) {
    queueKeysToTry.push(String(key));
    triedKeys.add(String(key));
  }
}

// 2) varre filasCatalogo e inclui filas cujo nome case com padrões comuns de suporte (N1/N2/N3) ou financeiro
const patterns = [
  /\bn1\b/i,
  /\bn2\b/i,
  /\bn3\b/i,
  /\bn1[-\s]?suporte\b/i,
  /\bn2[-\s]?suporte\b/i,
  /\bn3[-\s]?suporte\b/i,
  /\bsuporte\b/i,
  /\bfinanceiro\b/i
];

for (const key in filasCatalogo) {
  if (triedKeys.has(String(key))) continue;
  const qName = String(filasCatalogo[key].queueName || '').trim();
  if (!qName) continue;
  const qNameNorm = qName.toLowerCase();
  const matches = patterns.some(rx => rx.test(qNameNorm));
  if (matches) {
    queueKeysToTry.push(String(key));
    triedKeys.add(String(key));
  }
}

// 3) se ainda vazio, adiciona fallback id como última tentativa
if (queueKeysToTry.length === 0) {
  const fallbackKey = resolveQueueKeyByName(filasCatalogo, FILA_FALLBACK_NOME) || String(FILA_FALLBACK_ID);
  queueKeysToTry.push(String(fallbackKey));
  triedKeys.add(String(fallbackKey));
}

if (DEBUG) console.log('queueKeysToTry:', queueKeysToTry.map(k => ({ key: k, name: filasCatalogo[k]?.queueName || k })));

// tentativa sequencial: para cada fila, tenta escolher atendente apenas entre online
let chosen = null;
let chosenModo = null;
let chosenUsuariosDaFila = [];
let chosenQueueKey = null;
let chosenQueueId = null;
let chosenQueueName = null;

for (const qKey of queueKeysToTry) {
  const preferidosForThis = (String(qKey) === String(targetQueueKey)) ? preferidos : (DEPTO_PREFERIDOS['suporte'] || []);
  const res = escolherAtendentePorCarga(qKey, preferidosForThis, filasCatalogo, usuariosPorId, false);
  if (res.atendente) {
    chosen = res.atendente;
    chosenModo = res.modo;
    chosenUsuariosDaFila = res.usuariosDaFila;
    chosenQueueKey = qKey;
    chosenQueueId = filasCatalogo[qKey]?.queueId ?? qKey;
    chosenQueueName = filasCatalogo[qKey]?.queueName ?? (typeof qKey === 'string' ? qKey : String(qKey));
    break;
  }
  // continua para próxima fila se res.atendente == null
}

// Se não encontrou em nenhuma fila escalonada, transfere para fila fallback e NÃO atribui usuário (userId = null)
let redirectedToFallback = false;
if (!chosen) {
  redirectedToFallback = true;
  const fallbackKey = resolveQueueKeyByName(filasCatalogo, FILA_FALLBACK_NOME) || resolveQueueKeyByName(filasCatalogo, 'n1-suporte') || String(FILA_FALLBACK_ID);
  const fallbackPreferidos = DEPTO_PREFERIDOS['suporte'] || [];

  // tenta escolher na fallback apenas entre online
  const fallbackRes = escolherAtendentePorCarga(fallbackKey, fallbackPreferidos, filasCatalogo, usuariosPorId, false);

  if (fallbackRes.atendente) {
    chosen = fallbackRes.atendente;
    chosenModo = `redirected_${fallbackRes.modo}`;
    chosenUsuariosDaFila = fallbackRes.usuariosDaFila;
    chosenQueueKey = fallbackKey;
    chosenQueueId = filasCatalogo[fallbackKey]?.queueId ?? fallbackKey;
    chosenQueueName = filasCatalogo[fallbackKey]?.queueName ?? FILA_FALLBACK_NOME;
  } else {
    // fallback também não tem online: retorna fila fallback com userId = null (sem atribuir usuário offline)
    chosen = null;
    chosenModo = 'fallback_no_online';
    chosenUsuariosDaFila = fallbackRes.usuariosDaFila || [];
    chosenQueueKey = fallbackKey;
    chosenQueueId = filasCatalogo[fallbackKey]?.queueId ?? fallbackKey;
    chosenQueueName = filasCatalogo[fallbackKey]?.queueName ?? FILA_FALLBACK_NOME;
